def solve_f(n, c):
    colorings = get_no_brbr_colorings(n)
    num_s = len(colorings)
    subsets = []
    for size in range(c + 1):
        for comb in itertools.combinations(range(n), size):
            subsets.append(set(comb))

    # Precompute rotations of subsets
    subset_rotations = [] # subset_rotations[i][r] = subsets[i] + r
    for s in subsets:
        rots = []
        for r in range(n):
            rots.append({ (p + r) % n for p in s })
        subset_rotations.append(rots)

    f = [None] * num_s
    def backtrack(s_idx):
        if s_idx == num_s:
            return True
        for subset_idx in range(len(subsets)):
            # Consistency check
            consistent = True
            P_new = subsets[subset_idx]
            S_new = colorings[s_idx]
            for prev_idx in range(s_idx):
                P_prev_idx = f[prev_idx]
                S_prev = colorings[prev_idx]
                # Check all r such that P_new + r == P_prev
                for r in range(n):
                    if subset_rotations[subset_idx][r] == subsets[P_prev_idx]:
                        # Check S_new[p] == S_prev[(p + r) % n]
                        for p in P_new:
                            if S_new[p] != S_prev[(p + r) % n]:
                                consistent = False
                                break
                        if not consistent: break
                if not consistent: break

            if consistent:
                f[s_idx] = subset_idx
                if backtrack(s_idx + 1):
                    return True
                f[s_idx] = None
        return False

    if backtrack(0):
        return True
    return False

